let voiceProjects=[],voiceProject=null;
const beforeVoiceStudio=render;
render=function(){if(location.hash!=='#voice-studio')return beforeVoiceStudio();document.getElementById('app').innerHTML=integratedShell('voice-studio',heading('Voice & digital-human drafts','Scholarion Academy · Local storyboard workspace')+`<section class="card prose"><strong>AI disclosure: fictional persona designs. No speech, video or lip-sync is generated.</strong><p id="voice-status" role="status">Connecting…</p><label>Course context<select id="voice-course"></select></label><div id="voice-capabilities"></div><form id="voice-create"><label>Project title<input name="title" maxlength="160" required></label><button class="button">Create storyboard</button></form></section><div id="voice-projects"></div><div id="voice-detail"></div>`,model.role);bind();normalizeWorkspace();loadVoiceStudio();};
async function loadVoiceStudio(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';const d=await workspaceApi('voice-studio/status'),p=await workspaceApi('voice-studio/list');if(location.hash!=='#voice-studio')return;voiceProjects=p.projects;document.getElementById('voice-course').innerHTML=workspaceSession.courses.map(c=>`<option ${selectedCourse===c?'selected':''}>${esc(c)}</option>`).join('');document.getElementById('voice-status').textContent='Connected to local draft storage. Models and external connectors unavailable.';document.getElementById('voice-capabilities').innerHTML=`<details><summary>Capability status and blockers</summary>${d.capabilities.map(x=>`<p><b>${esc(x.capability)} · ${esc(x.status)}</b><br>${esc(x.blocker)}</p>`).join('')}</details><p>${d.personas.map(p=>esc(p.name)+' — fictional design; no verified speech languages').join(' · ')}</p>`;document.getElementById('voice-projects').innerHTML=p.projects.map(x=>`<section class="card prose"><h2>${esc(x.title)}</h2><p>Revision ${x.revision} · ${x.scenes.length} scenes · ${x.archived?'Archived':'Draft'}</p><button class="button secondary" data-voice-open="${x.id}">Open storyboard</button></section>`).join('');}catch(e){document.getElementById('voice-status').textContent=e.message+' — Connect an authorized instructor account.';}}
function showVoiceProject(p){voiceProject=p;document.getElementById('voice-detail').innerHTML=`<section class="card prose"><h2>${esc(p.title)}</h2><p>Revision ${p.revision} · SIMULATED media workflow; saved script draft</p>${p.scenes.map(s=>`<article><h3>${esc(s.speaker)} · ${esc(s.avatar)}</h3><p>${esc(s.script)}</p><small>${esc(s.voice)} · ${esc(s.language)}</small></article>`).join('')}<form id="voice-scene"><h3>Add scene</h3><label>Speaker identifier<input name="speaker" required maxlength="80"></label><label>Persona<select name="avatar"><option value="amara">Amara</option><option value="tunde">Tunde</option></select></label><label>English draft script<textarea name="script" maxlength="4000" required></textarea></label><button class="button" ${p.archived?'disabled':''}>Save scene</button></form><form id="voice-change"><h3>Change all scenes for one speaker</h3><label>Speaker identifier<input name="speaker" required></label><label>Replacement persona<select name="avatar"><option value="amara">Amara</option><option value="tunde">Tunde</option></select></label><button class="button secondary" ${p.archived?'disabled':''}>Preview affected scenes</button></form><div id="voice-change-preview"></div><form id="voice-restore"><label>Restore earlier revision<input name="target" type="number" min="1" max="${p.revision}" required></label><button class="button secondary">Restore as new version</button></form><button class="button secondary" id="voice-export">Export storyboard JSON</button> <button class="button secondary" id="voice-archive">Archive draft</button><p>Generation, capture, cloning and publication are disabled. Script exports contain no media watermark or signed provenance.</p></section>`;}
document.addEventListener('change',e=>{if(e.target.id==='voice-course'){selectedCourse=e.target.value;voiceProject=null;document.getElementById('voice-detail').innerHTML='';loadVoiceStudio();}});
document.addEventListener('submit',async e=>{if(!['voice-create','voice-scene','voice-change','voice-restore'].includes(e.target.id))return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),b=f.querySelector('button');b.disabled=true;try{let p;if(f.id==='voice-create')p=await workspaceApi('voice-studio/create',{title:d.title});else{const base={id:voiceProject.id,revision:voiceProject.revision};if(f.id==='voice-change'){const payload={...base,speaker:d.speaker,avatar:d.avatar,voice:d.avatar+'-synthetic-design',language:'en'};const preview=await workspaceApi('voice-studio/change-all',{...payload,dryRun:true});const host=document.getElementById('voice-change-preview');host.textContent=`${preview.count} scenes for ${d.speaker} will change. Other speakers remain unchanged. `;const confirm=document.createElement('button');confirm.className='button';confirm.textContent='Confirm change';confirm.onclick=async()=>{confirm.disabled=true;try{const result=await workspaceApi('voice-studio/change-all',{...payload,confirmed:true});await loadVoiceStudio();showVoiceProject(result);}catch(err){document.getElementById('voice-status').textContent=err.message;}};host.appendChild(confirm);return;}p=await workspaceApi('voice-studio/'+(f.id==='voice-scene'?'scene':'restore'),{...base,...(f.id==='voice-scene'?{speaker:d.speaker,avatar:d.avatar,voice:d.avatar+'-synthetic-design',language:'en',script:d.script}:{targetRevision:Number(d.target)})});}await loadVoiceStudio();showVoiceProject(p);}catch(err){document.getElementById('voice-status').textContent=err.message;}finally{b.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-voice-open],#voice-export,#voice-archive');if(!b)return;try{if(b.dataset.voiceOpen)return showVoiceProject(voiceProjects.find(p=>p.id===b.dataset.voiceOpen));if(b.id==='voice-export'){const d=await workspaceApi('voice-studio/export',{id:voiceProject.id});download('storyboard-draft.json',JSON.stringify(d,null,2),'application/json');}else{const p=await workspaceApi('voice-studio/archive',{id:voiceProject.id,revision:voiceProject.revision});await loadVoiceStudio();showVoiceProject(p);}}catch(err){document.getElementById('voice-status').textContent=err.message;}});
render();
